(()=>{const $=id=>document.getElementById(id),field=$('weapon-field'),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;let timer=null,progress=0;
 for(let i=0;i<80;i++){const dot=document.createElement('i');dot.style.left=((i*37+11)%100)+'%';dot.style.top=((i*53+7)%100)+'%';document.querySelector('.field-dots').append(dot);}
 for(const [index,item]of TitleSprites.items.entries()){const button=document.createElement('button'),canvas=document.createElement('canvas'),label=document.createElement('span');button.type='button';button.className='floating-weapon';button.setAttribute('aria-label',item.name);for(const [key,value]of Object.entries({x:item.x+'%',y:item.y+'%','mobile-x':item.mx+'%','mobile-y':item.my+'%',size:item.size+'px',angle:item.angle+'deg',speed:(3+index*.23)+'s',delay:(-index*.7)+'s'}))button.style.setProperty('--'+key,value);canvas.setAttribute('aria-hidden','true');TitleSprites.draw(canvas,item.id);label.className='weapon-label';label.textContent=item.name;button.append(canvas,label);button.addEventListener('click',()=>{button.classList.remove('popped');void button.offsetWidth;button.classList.add('popped');});field.append(button);}
 TitleSprites.draw($('loading-weapon'),'umbrella');const skills=[...document.querySelectorAll('[data-skill]')],colors=['water','water','electric','water'];skills.forEach((c,i)=>{TitleSprites.draw(c,c.dataset.skill);c.parentElement.style.setProperty('--skill-color',GamePalette.tokens[colors[i]]);});
 const stage=p=>p<25?0:p<47?1:p<100?2:3;
 function render(){const step=stage(progress);$('loading-percent').replaceChildren(document.createTextNode(String(progress).padStart(2,'0')),Object.assign(document.createElement('span'),{textContent:'%'}));$('loading-fill').style.width=progress+'%';$('loading-track').setAttribute('aria-valuenow',String(progress));$('loading-status').textContent=progress===100?'말도 안 되는 무기, 준비 완료!':progress>=47?'네 기술에 움직임을 불어넣는 중':['낙서에 숨은 가능성을 찾는 중','평범한 우산에 엉뚱한 힘을 담는 중'][step];document.querySelectorAll('[data-stage]').forEach((li,i)=>{li.classList.toggle('active',i===step);li.classList.toggle('complete',i<step);});skills.forEach((canvas,i)=>canvas.parentElement.classList.toggle('ready',progress>=[56,69,83,96][i]));$('loading-heading').innerHTML=progress===100?'이딴 것도<br>무기가 됐다!':'잠깐, 이걸로<br>싸울 수 있다고?';$('loading-weapon').classList.toggle('finished',progress===100);document.querySelector('.loading-art-label').textContent=progress<47?'평범했던 우산':'폭풍을 뒤집는 우산';if(progress===100){clearInterval(timer);timer=null;$('loading-tip').lastElementChild.textContent='상상은 네가. 말도 안 되는 전투는 무기가.';}}
 function show(mode){clearInterval(timer);timer=null;const loading=mode==='loading';$('title-scene').hidden=loading;$('loading-scene').hidden=!loading;$('show-title').setAttribute('aria-pressed',String(!loading));$('show-loading').setAttribute('aria-pressed',String(loading));$('preview-note').textContent=loading?'LOADING SCREEN':'START SCREEN';if(loading){progress=0;$('loading-tip').lastElementChild.textContent='낙서의 모양이 네 기술의 정체성이 돼.';render();timer=setInterval(()=>{progress=Math.min(100,progress+(progress<47?2:1));render();},reduce?60:140);$('loading-back').focus({preventScroll:true});}else $('start-preview').focus({preventScroll:true});}
 $('start-preview').addEventListener('click',()=>show('loading'));$('show-title').addEventListener('click',()=>show('title'));$('show-loading').addEventListener('click',()=>show('loading'));$('loading-back').addEventListener('click',()=>show('title'));document.addEventListener('keydown',event=>{if(event.key==='Escape')show('title');if(event.key==='Enter'&&event.target===document.body){event.preventDefault();show('loading');}});window.addEventListener('pagehide',()=>clearInterval(timer));
})();
